def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            if v:
                counts[v] = counts.get(v, 0) + 1

    # The objects are grouped by color, left to right, and within each
    # color arranged from smallest to largest toward the bottom.
    seen = set()
    by_color = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            r0, c0 = min(r for r, c in cells), min(c for r, c in cells)
            shape = [(r-r0, c-c0) for r, c in cells]
            sh = max(r for r, c in shape) + 1
            sw = max(c for r, c in shape) + 1
            by_color.setdefault(color, []).append((len(cells), sh, sw, shape))

    out = [[0] * w for _ in range(h)]
    # Order color groups by their leftmost position in the input.
    colors = sorted(by_color, key=lambda col: min(c for r, c in
                      [(r,c) for r in range(h) for c in range(w) if grid[r][c] == col]))
    xbase = 0
    for color in colors:
        shapes = sorted(by_color[color], key=lambda x: x[0])
        total_h = sum(item[1] for item in shapes) + len(shapes) - 1
        y = h - total_h
        for _, sh, sw, shape in shapes:
            for dr, dc in shape:
                rr, cc = y + dr, xbase + dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = color
            y += sh + 1
        xbase += max(item[2] for item in shapes) + 1
    return out
